import { z } from 'zod';

import { PermanentJobError, type ReceivedJob } from './delivery-pump';
import type { Logger } from './logger';

const probeJobSchema = z.object({
  type: z.literal('worker.probe'),
  version: z.literal(1),
  commandId: z.string().uuid(),
  traceId: z.string().trim().min(1).max(128).optional(),
});

interface ProbeDependencies {
  database(): Promise<void>;
  objectStorage(): Promise<void>;
}

/**
 * Deployment-only command. It proves queue, database and private-storage access without changing
 * domain data. Issue #278 adds the versioned batch validation handler behind this same boundary.
 */
export function createProbeJobHandler(
  dependencies: ProbeDependencies,
  logger: Logger,
  delayMs = 0,
) {
  return async (message: ReceivedJob, signal: AbortSignal): Promise<void> => {
    const result = probeJobSchema.safeParse(message.body);
    if (!result.success) {
      throw new PermanentJobError(
        'UnsupportedJobContract',
        'The worker supports only the worker.probe version 1 deployment command.',
      );
    }
    if (signal.aborted) throw new Error('Worker shutdown interrupted the probe job.');

    if (delayMs > 0) {
      await new Promise<void>((resolve, reject) => {
        const timeout = setTimeout(resolve, delayMs);
        signal.addEventListener(
          'abort',
          () => {
            clearTimeout(timeout);
            reject(new Error('Worker shutdown interrupted the probe job.'));
          },
          { once: true },
        );
      });
    }

    await Promise.all([dependencies.database(), dependencies.objectStorage()]);
    if (signal.aborted) throw new Error('Worker shutdown interrupted the probe job.');
    logger.info('Deployment probe job verified worker dependencies.', {
      messageId: message.messageId,
      commandId: result.data.commandId,
      traceId: result.data.traceId,
    });
  };
}
import type { Logger } from './logger';

export interface ReceivedJob {
  body: unknown;
  deliveryCount: number;
  messageId: string;
}

export interface DeliverySubscription {
  close(): Promise<void>;
}

export interface DeliveryReceiver {
  subscribe(handlers: {
    processError(error: Error): Promise<void>;
    processMessage(message: ReceivedJob): Promise<void>;
  }): DeliverySubscription;
  complete(message: ReceivedJob): Promise<void>;
  abandon(message: ReceivedJob): Promise<void>;
  deadLetter(message: ReceivedJob, reason: string, description: string): Promise<void>;
  close(): Promise<void>;
}

export interface DeliveryMetrics {
  active: number;
  abandoned: number;
  completed: number;
  deadLettered: number;
  deliveryErrors: number;
  received: number;
}

export class PermanentJobError extends Error {
  constructor(
    readonly reason: string,
    message: string,
  ) {
    super(message);
    this.name = 'PermanentJobError';
  }
}

type JobHandler = (message: ReceivedJob, signal: AbortSignal) => Promise<void>;

export class DeliveryPump {
  private readonly controller = new AbortController();
  private readonly activeTasks = new Set<Promise<void>>();
  private subscription: DeliverySubscription | undefined;
  private stopping = false;
  readonly metrics: DeliveryMetrics = {
    active: 0,
    abandoned: 0,
    completed: 0,
    deadLettered: 0,
    deliveryErrors: 0,
    received: 0,
  };

  constructor(
    private readonly receiver: DeliveryReceiver,
    private readonly handler: JobHandler,
    private readonly logger: Logger,
  ) {}

  start(): void {
    if (this.subscription) throw new Error('Delivery pump has already started.');
    this.subscription = this.receiver.subscribe({
      processMessage: async (message) => this.track(message),
      processError: async (error) => {
        this.metrics.deliveryErrors += 1;
        this.logger.error('Job transport delivery error.', { errorName: error.name });
      },
    });
    this.logger.info('Job delivery pump started.');
  }

  private track(message: ReceivedJob): Promise<void> {
    const task = this.process(message);
    this.activeTasks.add(task);
    this.metrics.active = this.activeTasks.size;
    const removeTask = () => {
      this.activeTasks.delete(task);
      this.metrics.active = this.activeTasks.size;
    };
    // Use both handlers so the cleanup promise cannot become an unhandled rejection.
    void task.then(removeTask, removeTask);
    return task;
  }

  private async process(message: ReceivedJob): Promise<void> {
    this.metrics.received += 1;
    this.logger.info('Job delivery received.', {
      messageId: message.messageId,
      deliveryCount: message.deliveryCount,
    });

    if (this.stopping) {
      await this.receiver.abandon(message);
      this.metrics.abandoned += 1;
      return;
    }

    try {
      await this.handler(message, this.controller.signal);
      await this.receiver.complete(message);
      this.metrics.completed += 1;
      this.logger.info('Job delivery completed.', { messageId: message.messageId });
    } catch (error) {
      if (error instanceof PermanentJobError) {
        await this.receiver.deadLetter(message, error.reason, error.message);
        this.metrics.deadLettered += 1;
        this.logger.warn('Job delivery dead-lettered.', {
          messageId: message.messageId,
          reason: error.reason,
        });
        return;
      }

      await this.receiver.abandon(message);
      this.metrics.abandoned += 1;
      this.logger.warn('Job delivery abandoned for retry.', {
        messageId: message.messageId,
        errorName: error instanceof Error ? error.name : 'UnknownError',
      });
    }
  }

  async stop(timeoutMs: number): Promise<boolean> {
    if (this.stopping) return this.activeTasks.size === 0;
    this.stopping = true;
    this.logger.info('Stopping job delivery pump.', { active: this.activeTasks.size });
    // Begin stopping deliveries immediately. Some SDK implementations wait for active
    // handlers in close(), so do not let that consume the worker's whole drain budget.
    const subscriptionClosed = this.subscription?.close() ?? Promise.resolve();

    let timeout: NodeJS.Timeout | undefined;
    const drained = await Promise.race([
      Promise.allSettled([...this.activeTasks]).then(() => true),
      new Promise<false>((resolve) => {
        timeout = setTimeout(() => resolve(false), timeoutMs);
      }),
    ]);
    if (timeout) clearTimeout(timeout);
    if (!drained) {
      this.controller.abort();
      this.logger.warn(
        'Worker drain deadline expired; active locks will recover by abandon or expiry.',
        {
          active: this.activeTasks.size,
        },
      );
      await Promise.race([
        Promise.allSettled([...this.activeTasks]),
        new Promise<void>((resolve) => setTimeout(resolve, 1_000)),
      ]);
    }
    await Promise.race([
      subscriptionClosed,
      new Promise<void>((resolve) => setTimeout(resolve, 1_000)),
    ]);
    await this.receiver.close();
    return drained;
  }
}
import { readFileSync } from 'node:fs';
import { resolve } from 'node:path';

import { DefaultAzureCredential } from '@azure/identity';
import {
  ServiceBusClient,
  type ServiceBusReceivedMessage,
  type ServiceBusReceiver,
} from '@azure/service-bus';
import { BlobServiceClient, type ContainerClient } from '@azure/storage-blob';
import { FilesystemObjectStore, type ObjectStore } from '@sport-analytics/object-storage';
import { Pool } from 'pg';

import { AzureBlobObjectStore } from './azure-blob-object-store';
import type { WorkerEnvironment } from './config';
import { DatabaseDeliveryReceiver } from './database-delivery-receiver';
import type { DeliveryReceiver, DeliverySubscription, ReceivedJob } from './delivery-pump';
import type { OutboxSender } from './outbox-relay';

interface AzureReceivedJob extends ReceivedJob {
  raw: ServiceBusReceivedMessage;
}
function requireAzureMessage(message: ReceivedJob): AzureReceivedJob {
  if (!('raw' in message)) throw new Error('The received job has no Azure message context.');
  return message as AzureReceivedJob;
}

class AzureServiceBusDeliveryReceiver implements DeliveryReceiver {
  constructor(
    private readonly receiver: ServiceBusReceiver,
    private readonly concurrency: number,
  ) {}
  subscribe(handlers: {
    processError(error: Error): Promise<void>;
    processMessage(message: ReceivedJob): Promise<void>;
  }): DeliverySubscription {
    return this.receiver.subscribe(
      {
        processError: async (args) => handlers.processError(args.error),
        processMessage: async (raw) => {
          const message: AzureReceivedJob = {
            raw,
            body: raw.body,
            deliveryCount: raw.deliveryCount ?? 1,
            messageId: String(raw.messageId ?? 'missing-message-id'),
          };
          await handlers.processMessage(message);
        },
      },
      { autoCompleteMessages: false, maxConcurrentCalls: this.concurrency },
    );
  }
  complete(message: ReceivedJob) {
    return this.receiver.completeMessage(requireAzureMessage(message).raw);
  }
  abandon(message: ReceivedJob) {
    return this.receiver.abandonMessage(requireAzureMessage(message).raw);
  }
  deadLetter(message: ReceivedJob, reason: string, description: string) {
    return this.receiver.deadLetterMessage(requireAzureMessage(message).raw, {
      deadLetterReason: reason,
      deadLetterErrorDescription: description,
    });
  }
  close() {
    return this.receiver.close();
  }
}

export interface RuntimeDependencies {
  checks: {
    database(): Promise<void>;
    objectStorage(): Promise<void>;
    serviceBus(): Promise<void>;
  };
  close(): Promise<void>;
  database: Pool;
  deliveryReceiver: DeliveryReceiver;
  outboxSender: OutboxSender;
  useOutboxRelay: boolean;
  ingestionObjectStorage: Pick<ObjectStore, 'read'>;
  releaseObjectStorage: ObjectStore;
}

async function checkPrivate(container: ContainerClient) {
  const properties = await container.getProperties();
  if (properties.blobPublicAccess !== undefined)
    throw new Error('Configured object-storage container permits public access.');
}

export function createRuntimeDependencies(environment: WorkerEnvironment): RuntimeDependencies {
  const database = new Pool({
    connectionString: environment.DATABASE_URL,
    ssl:
      environment.DATABASE_SSL_MODE === 'disable'
        ? false
        : { ca: readFileSync(environment.DATABASE_CA_CERT_PATH, 'utf8'), rejectUnauthorized: true },
    max: Math.max(2, environment.WORKER_CONCURRENCY + 1),
    connectionTimeoutMillis: 10_000,
    idleTimeoutMillis: 30_000,
    // Sent as a PostgreSQL startup parameter, so every connection this pool
    // opens carries the bound. A cancelled statement inside a transaction
    // aborts that transaction, which the job lease then retries.
    statement_timeout: environment.DATABASE_STATEMENT_TIMEOUT_MS,
    application_name: 'sport-analytics-worker',
  });
  database.on('error', () => console.error('Unexpected PostgreSQL worker pool error.'));

  const closeables: Array<{ close(): Promise<void> }> = [];
  let ingestionObjectStorage: ObjectStore;
  let releaseObjectStorage: ObjectStore;
  let storageCheck: () => Promise<void>;
  const credential = new DefaultAzureCredential(
    environment.AZURE_CLIENT_ID
      ? { managedIdentityClientId: environment.AZURE_CLIENT_ID }
      : undefined,
  );

  if (environment.OBJECT_STORAGE_PROVIDER === 'azure') {
    const account = environment.AZURE_STORAGE_ACCOUNT_NAME!;
    const ingestionName =
      environment.AZURE_STORAGE_INGESTION_CONTAINER_NAME ??
      environment.AZURE_STORAGE_CONTAINER_NAME!;
    const releaseName = environment.AZURE_STORAGE_RELEASE_CONTAINER_NAME!;
    const blobService = new BlobServiceClient(
      `https://${account}.blob.core.windows.net`,
      credential,
    );
    const ingestion = blobService.getContainerClient(ingestionName);
    const releases = blobService.getContainerClient(releaseName);
    ingestionObjectStorage = new AzureBlobObjectStore(ingestion);
    releaseObjectStorage = new AzureBlobObjectStore(releases);
    storageCheck = async () => {
      await Promise.all([checkPrivate(ingestion), checkPrivate(releases)]);
    };
  } else {
    const root = environment.OBJECT_STORAGE_FILESYSTEM_ROOT!;
    ingestionObjectStorage = new FilesystemObjectStore(resolve(root, 'staged-ingestion'));
    releaseObjectStorage = new FilesystemObjectStore(resolve(root, 'dataset-releases'));
    storageCheck = async () => undefined;
  }

  let deliveryReceiver: DeliveryReceiver;
  let outboxSender: OutboxSender;
  let serviceBusCheck: () => Promise<void>;
  let useOutboxRelay = false;
  if (environment.WORKER_TRANSPORT_PROVIDER === 'azure-service-bus') {
    const serviceBus = new ServiceBusClient(
      environment.SERVICE_BUS_FULLY_QUALIFIED_NAMESPACE!,
      credential,
    );
    const sender = serviceBus.createSender(environment.SERVICE_BUS_QUEUE_NAME!);
    const receiver = serviceBus.createReceiver(environment.SERVICE_BUS_QUEUE_NAME!, {
      receiveMode: 'peekLock',
      maxAutoLockRenewalDurationInMs: environment.SERVICE_BUS_LOCK_RENEWAL_MS,
    });
    const healthReceiver = serviceBus.createReceiver(environment.SERVICE_BUS_QUEUE_NAME!, {
      receiveMode: 'peekLock',
    });
    closeables.push(sender, healthReceiver, serviceBus);
    deliveryReceiver = new AzureServiceBusDeliveryReceiver(
      receiver,
      environment.WORKER_CONCURRENCY,
    );
    outboxSender = {
      async send(messages) {
        for (const message of messages)
          await sender.sendMessages({
            messageId: message.messageId,
            body: message.body,
            contentType: 'application/json',
          });
      },
    };
    serviceBusCheck = async () => {
      await healthReceiver.peekMessages(1);
    };
    useOutboxRelay = true;
  } else {
    deliveryReceiver = new DatabaseDeliveryReceiver(
      database,
      environment.workerId,
      environment.OUTBOX_POLL_INTERVAL_MS,
    );
    outboxSender = {
      async send() {
        throw new Error('The local database transport does not use an outbox relay.');
      },
    };
    serviceBusCheck = async () => {
      await database.query('SELECT 1');
    };
  }

  return {
    checks: {
      async database() {
        await database.query('SELECT 1');
      },
      objectStorage: storageCheck,
      serviceBus: serviceBusCheck,
    },
    database,
    deliveryReceiver,
    outboxSender,
    useOutboxRelay,
    ingestionObjectStorage,
    releaseObjectStorage,
    async close() {
      await Promise.allSettled([...closeables.map((item) => item.close()), database.end()]);
    },
  };
}
# Issue #463 - Dev batch worker deployment and live acceptance

**Dates:** 10-11 September 2026
**Issue:** #463 - Provision dev batch worker and Service Bus pipeline
**Merged via:** PR #464

## Problem observed

Deployed season/back-catalogue batch submissions remained in `stored` state with zero accepted and rejected items because the development Azure environment did not contain the asynchronous worker and Service Bus resources required to process queued `batch.validate` jobs.

The repository already contained the batch worker, outbox/queue architecture and infrastructure definitions, but the development environment had not been provisioned and the deployment path had not yet been exercised end to end.

## Root causes and fixes

### Development worker infrastructure had not been provisioned

The initial #463 work provisioned and verified the development worker path:

- Azure Container App worker;
- Service Bus namespace and `batch-ingestion` queue;
- staged-ingestion Blob access;
- managed identities and RBAC;
- Key Vault database reference;
- Azure Container Registry image deployment; and
- hosted/manual worker deployment workflow.

### Deployment-path defects

The first live deployment exposed several deployment defects, all corrected under #463:

- Gitea runner did not provide Azure CLI;
- Bicep cross-scope references prevented role-assignment deployment;
- generated Service Bus namespace used a reserved suffix;
- ACR Tasks were unavailable on the student subscription, so the worker image is built on the Gitea runner and pushed to ACR;
- the active-revision health query selected the wrong projection;
- deployment health checks now wait for the active revision to become healthy; and
- Docker layer caching was introduced to make repeated hosted worker builds practical.

### Runtime defect: Service Bus publication

The worker initially logged repeated publish failures while the queue remained empty.

Manual checks proved:

- the runtime managed identity had sender/receiver roles;
- Service Bus connectivity from the worker succeeded;
- the queued outbox commands were structurally valid; and
- the queue had partitioning and duplicate detection enabled.

The worker was publishing multiple distinct messages in one broker batch. With the deployed queue configuration, this failed.

The runtime dependency was changed to publish each outbox command individually.

After deployment, logs showed successful command publication and delivery receipt. Previously stored commands were recovered and processed **without resubmitting their source batches**.

### Runtime defect: batch finalisation enum cast

Once messages were delivered, batch validation reached finalisation but failed repeatedly.

A rollback-only SQL reproduction isolated PostgreSQL error `42804`: the mapping-decision `CASE` expression returned text while the destination column uses the `batch_reference_mapping_state` enum.

The finalisation query was corrected with explicit enum casts:

```sql
THEN 'applied'::batch_reference_mapping_state
ELSE 'failed'::batch_reference_mapping_state
```

After deployment, fresh invalid batches ended deterministically as `rejected` rather than exhausting retries and becoming `failed`.

## Azure dependency verification

Live checks from the worker proved:

- PostgreSQL connectivity succeeded repeatedly;
- staged Blob access succeeded;
- Service Bus send succeeded;
- outbox commands were published;
- queue deliveries were received; and
- the worker could finalise jobs successfully.

The active feature-branch worker image used for live functional acceptance was:

```text
Revision: statsthegame-dev-batch-worker--0000004
Health: Healthy
Provisioning: Provisioned
Image SHA: 17b8244c7f4a07d6a30dc5646c71d1ab4483a4aa
```

That commit contains the accepted #463 runtime fixes and is part of the merged history.

### Post-merge deployment from `main`

**Status:** PASS

After #463 was merged, the worker deployment workflow was rerun from `main`.

Observed active revision:

```text
Revision: statsthegame-dev-batch-worker--0000005
Health: Healthy
Provisioning: Provisioned
Image: .../sport-analytics-worker:06815e9f725056db14c090139b5785a08b09723c
```

Azure Container Apps reported `activeRevisionsMode = Single`. The new `main` revision was healthy and active.

This closes the final deployment gate: the live worker is healthy and is running an immutable image built from `main`.

## Live functional acceptance

### 1. Reference-resolution/conflict validation

Batch:

```text
3b072768-b7bf-4308-b2b3-ac8ad22b0794
```

resolved the fixture, competition, innings and all participant references successfully.

The item was then correctly rejected as:

```text
PUBLISHED_DELIVERY_CONFLICT
```

because the staged event occupied the same canonical delivery position as published delivery `4157` but had different run/extras content.

This proved the worker was no longer failing at infrastructure/finalisation and was enforcing cricket-content conflict validation.

### 2. Positive staged-batch acceptance

A corrected package was generated from the known published delivery at innings `41`, over `0`, position `0`.

Batch:

```text
f65118c3-3367-47d8-9d2d-5f29469225ff
```

Live UI result:

```text
Awaiting review
1 accepted
0 rejected
```

The batch appeared in the global reviewer queue.

This satisfies the original #463 acceptance requirement that a valid stored batch can progress through the asynchronous worker and become reviewable.

### 3. Reviewer report regression found and corrected

Opening the newly accepted review initially failed with:

```text
This review could not be loaded.
```

Azure API logs proved the report endpoint itself returned HTTP `200`.

The frontend shared report contract incorrectly required:

```ts
positionInOver: z.number().int().positive().nullable();
```

while cricket delivery positions are zero-based and the accepted event used `positionInOver: 0`.

The report contract was corrected to `nonnegative()` with regression coverage. After deployment, the existing awaiting-review batch loaded successfully without resubmission.

This defect was tracked/fixed separately and did not require changes to the worker pipeline.

### 4. Review and publication

The accepted batch was approved through the reviewer workspace.

Database evidence:

```text
batch.state = published
review.decision = approved
batch_item.state = duplicate_skipped
batch_item.published_event_id = 4157
```

Approval note:

```text
#463 acceptance test - valid staged batch using an existing published delivery.
```

The validation result recorded:

```text
EXACT_PUBLISHED_DUPLICATE
severity = warning
```

### 5. Duplicate-safe publication

The live canonical query for innings `41`, over `0`, position `0` returned exactly one delivery:

```text
deliveryId = 4157
ballNumber = 0.1
offBat = 0
extras = 1
total = 1
wides = 1
```

Live delivery count:

```text
1
```

Therefore approval of the exact published duplicate did **not** create a second canonical delivery or double-count the event.

## Acceptance matrix

| Criterion                                          | Result                             | Evidence                                                                              |
| -------------------------------------------------- | ---------------------------------- | ------------------------------------------------------------------------------------- |
| Worker exists and runs in dev                      | PASS                               | Healthy Container App revision                                                        |
| Service Bus queue exists                           | PASS                               | `batch-ingestion` queue provisioned and used                                          |
| PostgreSQL reachable from worker                   | PASS                               | repeated live DB connectivity checks                                                  |
| Staged Blob reachable from worker                  | PASS                               | live Blob access check                                                                |
| Outbox commands publish                            | PASS                               | worker logs showed successful command publication                                     |
| Worker receives validation jobs                    | PASS                               | live delivery receipt logs                                                            |
| Existing stored work recovers without resubmission | PASS                               | pending outbox commands processed after runtime fix                                   |
| Validation executes and finalises                  | PASS                               | conflict batch ended `rejected`, job `succeeded`, one attempt                         |
| Valid batch reaches review                         | PASS                               | batch `f65118c3-...` reached `awaiting_review`, 1 accepted / 0 rejected               |
| Global reviewer queue contains batch               | PASS                               | deployed reviewer queue displayed the batch                                           |
| Reviewer report loads                              | PASS after separate regression fix | zero-based report contract corrected                                                  |
| Approval is recorded                               | PASS                               | `batch_review_decision = approved`                                                    |

